  today = Date ( SV担当者入力データ月次::月 - 1 ; 1 ; SV担当者入力データ月次::年 ) ;

  // 取得対象の3か月の年月をそれぞれ算出
  y1 = Year ( today );
  m1 = Month ( today );

  date2 = Date ( m1 - 1 ; 1 ; y1 );
  y2 = Year ( date2 );
  m2 = Month ( date2 );

  date3 = Date ( m2 - 1 ; 1 ; y2 );
  y3 = Year ( date3 );
  m3 = Month ( date3 );


  m1Row = ExecuteSQL (
    "
    SELECT \"当月目標金額_月初_委託\",\"当月目標金額_月初_卸売\",\"月次着地額_月次_委託\",\"月次着地額_月次_卸売\"
    FROM \"SV担当者入力データ月次\"
    WHERE \"加盟店セットCD\" = ?
    AND (
      (\"年\" = ? AND \"月\" = ?) 
    )
    ";
    ","; "¶";
    SV担当者入力データ月次::加盟店セットCD;
    y1; m1
    ) ; 

  m2Row = ExecuteSQL (
    "
    SELECT \"当月目標金額_月初_委託\",\"当月目標金額_月初_卸売\",\"月次着地額_月次_委託\",\"月次着地額_月次_卸売\"
    FROM \"SV担当者入力データ月次\"
    WHERE \"加盟店セットCD\" = ?
    AND (
      (\"年\" = ? AND \"月\" = ?) 
    )
    ";
    ","; "¶";
    SV担当者入力データ月次::加盟店セットCD;
    y2; m2
    ) ; 

  m3Row = ExecuteSQL (
    "
    SELECT \"当月目標金額_月初_委託\",\"当月目標金額_月初_卸売\",\"月次着地額_月次_委託\",\"月次着地額_月次_卸売\"
    FROM \"SV担当者入力データ月次\"
    WHERE \"加盟店セットCD\" = ?
    AND (
      (\"年\" = ? AND \"月\" = ?) 
    )
    ";
    ","; "¶";
    SV担当者入力データ月次::加盟店セットCD;
    y3; m3
    ) ;

  m1Row = If ( not IsEmpty ( m1Row ) ; m1Row ; "設定金額なし,設定金額なし,設定金額なし,設定金額なし" ) ; 
  m2Row = If ( not IsEmpty ( m2Row ) ; m2Row ; "設定金額なし,設定金額なし,設定金額なし,設定金額なし" ) ; 
  m3Row = If ( not IsEmpty ( m3Row ) ; m3Row ; "設定金額なし,設定金額なし,設定金額なし,設定金額なし" ) ; 
  result = m3Row & ¶ & m2Row & ¶ & m1Row
  ];

  result 
) ]

