Step.StepText:
変数を設定 [ $batData; 値:Let(

 v$tmp =
  "move \"" & Replace ( Substitute ( $fullpath; "/"; Char( 92 ) ); 1; 1; "" ) & "\"" & " " & "\"" & $bkFolder & "\"";

 List( $batData; v$tmp )

) ]

Value.Calculation:
Let(

 v$tmp =
  "move \"" & Replace ( Substitute ( $fullpath; "/"; Char( 92 ) ); 1; 1; "" ) & "\"" & " " & "\"" & $bkFolder & "\"";

 List( $batData; v$tmp )

)

Step.StepText:
変数を設定 [ $batData; 値:Let(

[

 v$powershellcmd = 
	"@echo off" & ¶ & 
	"net session >NUL 2>nul" & ¶ & 
	"if %errorlevel% neq 0 (" & ¶ & 
	" @powershell start-process %~0 -verb runas" & ¶ & 
	")";


 v$mkdir = 
	"If not exist " & $bkFolder & " mkdir " & $bkFolder;


 v$return = 
	List( v$powershellcmd; v$mkdir; $batData )


];

v$return

) ]

